// Musical values are generated by a grammar, not read from source scores.
AM.practiceRhythm = (() => {
  const N=AM.notation,clone=x=>JSON.parse(JSON.stringify(x));
  const base=['w','h','q','e','s'];
  function values({shortest='q',dotted=false,triplets=false}={}){
    const ds=base.slice(0,base.indexOf(shortest)+1);
    return[...ds,...(dotted?ds.filter(d=>d!=='w'&&d!=='s').map(d=>d+'.'):[]),...(triplets?['et','qt']:[])];
  }
  // Any complete sequence of allowed values/rests is expressible; triplets are grouped.
  function supports(pattern,profile,len=4){
    const allowed=new Set(values(profile));let t=0;
    for(let i=0;i<pattern.length;i++){
      const d=typeof pattern[i]==='string'?pattern[i]:pattern[i].d;if(!allowed.has(d))return false;
      if(d.endsWith('t')){if(pattern.slice(i,i+3).some(n=>(typeof n==='string'?n:n.d)!==d)||i+3>pattern.length)return false;i+=2;t+=3*N.dur(d);}else t+=N.dur(d);
    }
    return Math.abs(t-len)<1e-9;
  }
  function generate(profile,{rng,length=4,dense=false,restChance=0,required}={}){
    const choose=xs=>xs[Math.floor(rng()*xs.length)],allowed=values(profile),cells=allowed.map(d=>d.endsWith('t')?[d,d,d]:[d]);
    const ticks=ds=>Math.round(ds.reduce((n,d)=>n+N.ticks(d),0));let remain=Math.round(length*24);const result=[],fillable=new Map([[0,true]]);
    const canFill=n=>{if(n<0)return false;if(fillable.has(n))return fillable.get(n);const ok=cells.some(ds=>canFill(n-ticks(ds)));fillable.set(n,ok);return ok;};
    while(remain){
      const options=cells.filter(ds=>ticks(ds)<=remain&&canFill(remain-ticks(ds))),weights=options.flatMap(ds=>Array(ds[0]===profile.shortest?(dense?8:3):ds[0]==='q'?5:ds[0]==='e'?4:1).fill(ds));
      if(!weights.length)throw Error('Unfillable rhythm');const ds=choose(weights);ds.forEach(d=>result.push({d,...(rng()<restChance?{r:1}:{})}));remain-=ticks(ds);
    }
    if(required&&allowed.includes(required)&&!required.endsWith('t')&&!result.some(n=>n.d===required)){
      const i=result.findIndex(n=>N.dur(n.d)>=2*N.dur(required)&&!n.d.endsWith('t'));
      if(i>=0){const original=result[i],count=N.dur(original.d)/N.dur(required);if(Number.isInteger(count))result.splice(i,1,...Array.from({length:count},()=>({d:required})));}
    }
    if(required?.endsWith('t')&&allowed.includes(required)&&!result.some(n=>n.d===required)){
      const i=result.findIndex(n=>Math.abs(N.dur(n.d)-3*N.dur(required))<1e-9);
      if(i>=0)result.splice(i,1,...Array.from({length:3},()=>({d:required})));
    }
    if(required&&allowed.includes(required)){
      const cell=required.endsWith('t')?[required,required,required]:[required],remaining=Math.round(length*24)-ticks(cell);
      if(!result.some(n=>n.d===required)&&canFill(remaining)){
        const tail=generate(profile,{rng,length:remaining/24,dense,restChance});
        result.splice(0,result.length,...cell.map(d=>({d})),...tail);
      }
      // A selected technical focus must occur as an attack, not exclusively
      // as a rest bearing the same duration symbol.
      const first=result.findIndex(n=>n.d===required);
      if(first>=0)for(let i=first;i<first+cell.length;i++)delete result[i].r;
    }
    for(let i=0;i<result.length;i++)if(result[i].d.endsWith('t')){result[i].tuplet=3;result[i+2].tupletEnd=true;i+=2;}
    return result;
  }
  function pulse(duration,count,pitch){return Array.from({length:count},()=>pitch===undefined?{r:1,d:duration}:{p:clone(pitch),d:duration});}
  function held(p,time,rest=false){
    const ds={'4/4':['w'],'3/4':['h.'],'12/8':['h.','h.'],'5/8':['h','e'],'7/8':['h.','e']}[time];
    return ds.map((d,i)=>rest?{r:1,d}:{p:clone(p),d,...(i<ds.length-1?{tie:1}:{})});
  }
  return{values,supports,generate,pulse,held};
})();
